template <typename UnionPtrType>
IdentityProviderPtr IdentityProvider::Clone() const {
  switch (tag_) {
    case Tag::kFederated:
      return NewFederated(
          mojo::Clone(*data_.federated));
    case Tag::kHolder:
      return NewHolder(
          mojo::Clone(*data_.holder));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, IdentityProvider>::value>::type*>
bool IdentityProvider::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kFederated:
      return mojo::Equals(*(data_.federated), *(other.data_.federated));
    case Tag::kHolder:
      return mojo::Equals(*(data_.holder), *(other.data_.holder));
  }

  return false;
}
